export function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function text(value,max,required=false){if(typeof value!=='string')value=value==null?'':String(value);value=value.trim();if(value.length>max||required&&!value)throw Error('A notebook field is missing or too long.');return value}
export function normalizeEntry(data){
  const date=text(data.date,10,true);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||isNaN(Date.parse(date+'T12:00:00'))||localDate(new Date(date+'T12:00:00'))!==date)throw Error('Choose a valid shift date.');
  const count=Number(data.count),confidence=Number(data.confidence);if(!Number.isInteger(count)||count<1||count>999||!Number.isInteger(confidence)||confidence<1||confidence>5)throw Error('Check the drink count and confidence rating.');
  const shots=data.shots===''||data.shots==null?null:Number(data.shots);if(shots!==null&&(!Number.isInteger(shots)||shots<0||shots>12))throw Error('Espresso shots must be from 0 to 12.');
  const lines=Array.isArray(data.steps)?data.steps:String(data.steps||'').split('\n');if(lines.length>60)throw Error('Keep a recipe to 60 steps or fewer.');const steps=lines.map(x=>text(x,1000).replace(/^\s*\d+[.)]\s*/,'')).filter(Boolean);if(steps.join('\n').length>6000)throw Error('Recipe steps are too long.');
  return {id:text(data.id,100,true),createdAt:text(data.createdAt,40,true),drink:text(data.drink,80,true),date,count,confidence,shots,size:text(data.size,60),milk:text(data.milk,60),steps,struggle:text(data.struggle,500),trainer:text(data.trainer,3000),vocab:text(data.vocab,500),notes:text(data.notes,3000),demo:data.demo===true};
}
export function validateBackup(data){if(!data||data.version!==1||!Array.isArray(data.entries)||!Array.isArray(data.attempts)||data.entries.length>10000||data.attempts.length>10000)throw Error('This is not a supported Barista Buddy backup.');const entries=data.entries.map(normalizeEntry);if(new Set(entries.map(x=>x.id)).size!==entries.length)throw Error('The backup contains duplicate entry IDs.');const ids=new Set(entries.map(x=>x.id));const attempts=data.attempts.map(x=>{if(!x||!['again','got-it'].includes(x.rating)||!ids.has(x.entryId))throw Error('The backup contains an invalid practice record.');return {id:text(x.id,100,true),cardId:text(x.cardId,200,true),entryId:text(x.entryId,100,true),rating:x.rating,date:text(x.date,40,true),demo:x.demo===true}});if(new Set(attempts.map(x=>x.id)).size!==attempts.length)throw Error('The backup contains duplicate practice IDs.');return {version:1,entries,attempts}}
export function aggregate(entries,attempts){return {shifts:new Set(entries.map(x=>x.date)).size,drinks:new Set(entries.map(x=>x.drink)).size,total:entries.reduce((s,x)=>s+x.count,0),attempts:attempts.length,gotIt:attempts.filter(x=>x.rating==='got-it').length,again:attempts.filter(x=>x.rating==='again').length}}
export function buildCards(entries,attempts,mode='recall',filter=null){
  const latest=new Map();[...entries].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)).forEach(e=>{if(!latest.has(e.drink))latest.set(e.drink,e)});const cards=[];
  for(const e of latest.values()){if(filter&&e.drink!==filter)continue;const add=(kind,question,answer)=>cards.push({id:e.id+':'+kind,entryId:e.id,drink:e.drink,date:e.date,demo:e.demo,question,answer,confidence:e.confidence});if(mode==='phrases'){if(e.vocab)add('vocab',`Which workplace phrase did you record for your ${e.drink}?`,e.vocab);continue}if(e.steps.length)add('steps',`How do you make your ${e.drink}?`,e.steps.map((s,i)=>`${i+1}. ${s}`).join('\n'));if(e.shots!==null)add('shots',`How many espresso shots did you record for your ${e.drink}${e.size?' ('+e.size+')':''}?`,`${e.shots} espresso ${e.shots===1?'shot':'shots'}`);if(e.milk)add('milk',`Which milk did you use for this ${e.drink}?`,e.milk);if(e.trainer)add('trainer',`What did your trainer suggest for your ${e.drink}?`,e.trainer)}
  const lastRating=id=>[...attempts].reverse().find(a=>a.cardId===id)?.rating;return cards.sort((a,b)=>(lastRating(a.id)==='again'?-10:0)+a.confidence-((lastRating(b.id)==='again'?-10:0)+b.confidence));
}
export function exampleEntries(){const ago=(n=0)=>{const d=new Date();d.setDate(d.getDate()-n);return localDate(d)};return [{id:'demo-cappuccino-1',drink:'Cappuccino',date:ago(2),count:5,size:'12 oz',shots:2,milk:'Whole milk',confidence:2,steps:['Dose and tamp the coffee.','Pull two espresso shots.','Steam the milk using the café’s routine.','Pour the milk and foam into the espresso.'],struggle:'My milk foam had big bubbles.',trainer:'Keep the pitcher steady. Ask me to check your steam-wand position.',vocab:'“Extra shot” means adding one more espresso shot.',notes:'Example training notes. Follow your own café’s recipe.'},{id:'demo-latte-1',drink:'Latte',date:ago(1),count:8,size:'12 oz',shots:2,milk:'Oat milk',confidence:4,steps:['Prepare the cup.','Dose, tamp, and pull two espresso shots.','Steam the oat milk as the trainer demonstrated.','Pour the milk into the espresso.'],struggle:'Remembering the milk alternative on the order.',trainer:'Repeat the order back before starting.',vocab:'“To go” means the customer wants a takeaway cup.',notes:''},{id:'demo-cappuccino-2',drink:'Cappuccino',date:ago(),count:6,size:'12 oz',shots:2,milk:'Whole milk',confidence:3,steps:['Dose and tamp the coffee.','Pull two espresso shots.','Steam the milk with the wand position my trainer showed me.','Pour the milk and foam into the espresso.'],struggle:'Milk texture is still inconsistent.',trainer:'Practice one pitcher with me before the rush.',vocab:'“Dairy-free” means no milk or ingredients made from animal milk.',notes:'The second try felt better.'},{id:'demo-americano-1',drink:'Americano',date:ago(),count:4,size:'12 oz',shots:2,milk:'None',confidence:4,steps:['Fill the cup with the café’s measured hot water.','Pull two espresso shots.','Add the espresso following the café’s routine.'],struggle:'',trainer:'Check the cup size before measuring the water.',vocab:'“Room for milk” means leaving some space at the top of the cup.',notes:''}].map((e,i)=>normalizeEntry({...e,createdAt:ago()+'T12:00:0'+i+'.000Z',demo:true}))}
